{
  "action": "question",
  "question_count": 1,
  "is_atomic": true,
  "atomic_questions": [
    "When you say the mission is successful only if at least two of the four key parts are destroyed, do you want the model to maximize the probability of achieving that success, or to guarantee (with certainty) that at least two parts are destroyed?"
  ],
  "rationale": "The response asks for a single policy choice between maximizing probability and guaranteeing certainty, which constitutes one semantically independent question."
}

